<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue';import type {RequestFn} from './media';import {traffic} from './lib';
type Row=Record<string,any>;const props=defineProps<{request:RequestFn,target?:Row}>();const emit=defineEmits<{changed:[],close:[]}>();
const panel=ref<HTMLElement>();let previousFocus:HTMLElement|null=null,previousOverflow:string|undefined,active=true;
function modalKeys(e:KeyboardEvent){if(!props.target)return;if(e.key==='Escape'){emit('close');return}if(e.key!=='Tab')return;const scope=panel.value?.closest('.modal')||panel.value;const items=Array.from(scope?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled])')||[]).filter(el=>el.getClientRects().length);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus()}}
onMounted(async()=>{if(!props.target)return;previousFocus=document.activeElement as HTMLElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();if(!active)return;panel.value?.querySelector<HTMLElement>('select')?.focus();document.addEventListener('keydown',modalKeys)});
onBeforeUnmount(()=>{active=false;document.removeEventListener('keydown',modalKeys);if(previousOverflow!==undefined)document.body.style.overflow=previousOverflow;if(previousFocus?.isConnected)previousFocus.focus()});
const kind=ref(props.target?.kind||'tickets'),action=ref(props.target?.archived_at?'restore':kind.value==='orders'||kind.value==='manual-payments'?'archive':'purge'),days=ref(props.target?0:90),preview=ref<Row|null>(null),result=ref<Row|null>(null),confirmed=ref(false),busy=ref(false),error=ref('');
const options:Record<string,string[][]>={tickets:[['purge','永久删除已关闭工单','删除工单正文及不再引用的图片，无法恢复。未关闭或近期有回复的工单受保护。']],orders:[['archive','移出当前列表','仅归档已取消、已退款或服务已失效的订单；财务与订阅凭据保留，可恢复显示。'],['restore','恢复归档显示','将已归档订单放回管理员当前列表，不改变服务和付款状态。'],['purge','永久删除无付款的已取消订单','仅删除无付款通道、无核款、无开通及续费关联、无后台任务的已取消过期订单。其他订单受保护。']], 'manual-payments':[['archive','移出核款列表','仅归档已结束记录，仍在待付款、提交审核或退款处理中的记录受保护；交易防重凭据保留。'],['restore','恢复归档显示','恢复管理员核款列表显示，不重复核款或开通。'],['attachments','永久清理归档附件','删除已归档且已结束记录的收款码快照、付款图片、已使用红包口令；保留流水、防重哈希、订单与开通账本。附件不可恢复。']],announcements:[['purge','永久删除已停用公告','删除已停用公告及不再引用的图片，正在展示的公告受保护。']]};
const detail=computed(()=>options[kind.value]?.find(x=>x[0]===action.value)?.[2]||'');
watch(kind,()=>{action.value=options[kind.value]?.[0]?.[0]||'purge'});watch([kind,action,days],()=>{preview.value=null;result.value=null;confirmed.value=false;error.value=''});
function body(){return{kind:kind.value,action:action.value,id:props.target?.id||'',days:days.value}}
async function check(){busy.value=true;error.value='';confirmed.value=false;try{preview.value=await props.request('admin/history-cleanup?'+new URLSearchParams(Object.entries(body()).map(([k,v])=>[k,String(v)])))}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
async function apply(){if(!confirmed.value||!preview.value?.eligible)return;busy.value=true;error.value='';try{result.value=await props.request('admin/history-cleanup','POST',{...body(),ids:preview.value.ids,confirmed:true});preview.value=null;confirmed.value=false;emit('changed')}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
</script>
<template><section ref="panel" class="panel history-cleanup"><h2>{{target?'处理历史记录':'历史记录与空间清理'}}</h2><p class="muted">历史记录主要占用磁盘，并非一直驻留内存。页面按上限读取；本入口每批最多处理 100 条，提交时重新检查状态。空间由 PostgreSQL 复用，文件大小不一定立即缩小。</p><p v-if="target" class="mono">{{target.name||target.subject||target.plan_name||target.id}} · {{target.id}}</p><div v-if="error" class="alert error">{{error}}</div><div v-if="result" class="alert" role="status">已处理 {{result.changed}} 条；移除 {{result.images_removed||0}} 张闲置图片，清理核款附件 {{traffic(result.attachment_bytes_removed||0,'auto')}}。{{result.message}}<p v-if="result.has_more">还有符合条件的记录，可再次预览并处理下一批。</p></div><form @submit.prevent="apply"><div class="fields"><label v-if="!target">记录类型<select v-model="kind" :disabled="busy"><option value="tickets">已关闭工单</option><option value="orders">历史订单</option><option value="manual-payments">已结束核款</option><option value="announcements">已停用公告</option></select></label><label>处理方式<select v-model="action" :disabled="busy"><option v-for="o in options[kind]" :key="o[0]" :value="o[0]">{{o[1]}}</option></select></label><label v-if="!target">早于多少天<input type="number" v-model.number="days" min="7" max="3650" required :disabled="busy"></label></div><p class="alert">{{detail}}</p><button type="button" :disabled="busy" @click="check">检查可处理记录</button><template v-if="preview"><p class="cleanup-count">本批符合条件 <strong>{{preview.eligible}}</strong> 条<span v-if="preview.has_more">（仍有更多）</span></p><p v-if="!preview.eligible" class="muted">没有符合条件的记录。待处理款项、有效服务、必要账本及时间范围外的记录不会删除。</p><label v-else class="multi"><input type="checkbox" v-model="confirmed" :disabled="busy">我已核对范围；永久清理的正文及附件无法恢复</label><button class="primary" :disabled="busy||!confirmed||!preview.eligible">确认执行本批操作</button></template></form><p v-if="!target" class="muted cleanup-more">后台任务及操作日志已自动限制保留时间与条数，也可在对应页面清理。此入口不删除付款防重、开通与续费账本，不执行阻塞业务的 VACUUM FULL。</p></section></template>
<style scoped>.history-cleanup h2{margin-bottom:12px}.cleanup-count{margin:16px 0}.cleanup-more{margin-top:22px}.history-cleanup .mono{margin:15px 0;overflow-wrap:anywhere}.history-cleanup .alert{font-size:12px;line-height:1.8}.history-cleanup form>button{margin-bottom:10px}</style>
